style.css:
@-moz-document domain("admin192c.acellus.com") {
/* Change the background for the main header */
header, .top-nav, .navbar, .site-header, .main-header {
    background-color: #f8f8f0 !important;  /* Light ivory */
}

/* Change footer or bottom sections */
footer, .footer-strip, .bottom-bar {
    background-color: #f8f8f0 !important;  /* Light ivory */
}

/* Apply to all content sections */
body, .content-area, .main-container, .page-wrapper {
    background-color: #f8f8f0 !important;  /* Light ivory for all main content */
}

/* Change sidebars, side navigation bars, or containers */
.sidebar, .side-nav, .side-bar-container {
    background-color: #f8f8f0 !important;  /* Light ivory for the sidebar */
}

/* Adjust class boxes to light ivory if necessary */
.class-box, .class-box-wrapper, .class-box-content {
    background-color: #f8f8f0 !important;  /* Light ivory for class boxes */
}

/* Ensure text areas contrast well */
.text, .content-text, .text-box, .class-box-title {
    color: #333333 !important;  /* Dark text to maintain readability */
}

/* Remove any dark blue borders if needed */
*, *::before, *::after {
    border-color: #f8f8f0 !important;  /* Light ivory borders for all elements */
}
}
